import {openForm,field,option,esc,$,$$} from './ui.js';

export function musicSummary(scene,state){
  const m=scene.music||(scene.musicAssetId?{mode:'play',assetId:scene.musicAssetId}:{mode:'keep'});
  if(m.mode==='stop')return 'Encerrar música com fade';
  if(m.mode!=='play')return 'Manter a música atual';
  return state.audioAssets.find(a=>a.id===m.assetId)?.name||state.playlists.find(p=>p.id===m.playlistId)?.name||'Escolher trilha';
}
const numberOrDefault=value=>value===''?undefined:Number(value);
export function openSceneMusic(ctx){
  const state=ctx.state(),scene=ctx.scene(),music=scene.music||(scene.musicAssetId?{mode:'play',assetId:scene.musicAssetId}:{mode:'keep'});
  const source=music.playlistId?'playlist:'+music.playlistId:music.assetId?'asset:'+music.assetId:'';
  openForm({title:`Música e ambiente · ${scene.title}`,wide:true,body:`<p class="dialog-description">Estas escolhas são aplicadas ao iniciar ou transicionar para esta cena. Você pode usar tempos diferentes para cada momento da história.</p><label class="field"><span>Ao iniciar a cena</span><select name="mode" id="sceneMusicMode">${[['keep','Manter a música atual'],['play','Iniciar ou trocar a música'],['stop','Encerrar a música']].map(([v,l])=>option(v,l,v===music.mode)).join('')}</select></label><section data-music-play><label class="field"><span>Faixa ou playlist</span><select name="source"><option value="">Escolher na biblioteca…</option><optgroup label="Faixas / YouTube">${state.audioAssets.map(a=>option('asset:'+a.id,a.name+(a.provider==='youtube'?' · YouTube':''),source==='asset:'+a.id)).join('')}</optgroup><optgroup label="Playlists do CRIS">${state.playlists.map(p=>option('playlist:'+p.id,p.name,source==='playlist:'+p.id)).join('')}</optgroup></select></label><div class="form-grid">${field('Volume da faixa (%)','volume',Math.round((music.volume??1)*100),'type="number" min="0" max="100" required')}${field('Começar em (segundos)','startSeconds',music.startSeconds??0,'type="number" min="0" step="1" required')}</div><div class="form-grid">${field('Primeira faixa da playlist','index',((music.playlistId?music.index:music.youtubeIndex)??0)+1,'type="number" min="1" step="1" required')}${field('Fade de entrada (s)','fadeIn',music.fadeIn??'','type="number" min="0" max="30" step="0.1" placeholder="Padrão: '+state.settings.musicFadeIn+'s"')}</div><label class="check-field"><input type="checkbox" name="loop" ${music.loop!==false?'checked':''}><span>Repetir a música até trocar ou encerrar</span></label><p class="form-hint">A repetição vale para faixas individuais; playlists continuam sua sequência.</p><p class="form-hint">No modo sequencial, a primeira faixa é 1. Se a playlist estiver em modo aleatório, a cena sorteia a faixa inicial. Para YouTube, a entrada começa quando o vídeo realmente toca. Arquivos locais permitem sobreposição completa.</p></section><section data-music-fade><label class="field"><span>Fade de saída da música anterior (s)</span><input name="fadeOut" type="number" min="0" max="30" step="0.1" value="${music.fadeOut??''}" placeholder="Padrão: ${state.settings.musicFadeOut}s"></label></section><hr><div class="form-grid"><label class="field"><span>Ambiente salvo ao iniciar</span><select name="ambienceId">${option('','Manter ambiente atual',!scene.ambienceId)}${option('stop','Encerrar ambiente salvo',scene.ambienceId==='stop')}${(state.ambiences||[]).map(a=>option(a.id,a.name,a.id===scene.ambienceId)).join('')}</select></label>${field('Transição do ambiente (s)','ambienceFade',scene.ambienceFade??'','type="number" min="0" max="30" step="0.1" placeholder="Fades do ambiente"')}</div><p class="form-hint">As camadas da cena e o ambiente salvo podem tocar juntos. Uma chuva contínua ajuda a sustentar a atmosfera durante a troca de trilha.</p>`,onReady:root=>{
    const update=()=>{const mode=$('#sceneMusicMode',root).value;const play=$('[data-music-play]',root),fade=$('[data-music-fade]',root);play.hidden=mode!=='play';fade.hidden=mode==='keep';$$('input,select',play).forEach(el=>el.disabled=play.hidden);$$('input',fade).forEach(el=>el.disabled=fade.hidden);};$('#sceneMusicMode',root).onchange=update;update();
  },onSubmit:form=>{
    const mode=form.get('mode'),value={mode};
    if(mode==='play'){
      const source=String(form.get('source')||'');if(!source)throw new Error('Escolha uma faixa ou playlist.');const [type,...id]=source.split(':');
      value[type==='playlist'?'playlistId':'assetId']=id.join(':');value.loop=form.has('loop');value.volume=Number(form.get('volume'))/100;value.startSeconds=Number(form.get('startSeconds'));value.index=Math.max(0,Number(form.get('index'))-1);value.youtubeIndex=value.index;value.fadeIn=numberOrDefault(form.get('fadeIn'));
    }
    if(mode!=='keep')value.fadeOut=numberOrDefault(form.get('fadeOut'));
    scene.music=value;delete scene.musicAssetId;scene.ambienceId=String(form.get('ambienceId'))||null;scene.ambienceFade=numberOrDefault(form.get('ambienceFade'));ctx.commit();
  }});
}
export function openMusicSettings(ctx){const settings=ctx.state().settings;openForm({title:'Transições musicais',body:`<p class="dialog-description">Defina o padrão da mesa. Cenas e cues podem escolher tempos próprios.</p><div class="form-grid">${field('Fade de entrada (s)','fadeIn',settings.musicFadeIn,'type="number" min="0" max="30" step="0.1" required')}${field('Fade de saída (s)','fadeOut',settings.musicFadeOut,'type="number" min="0" max="30" step="0.1" required')}</div><label class="check-field"><input type="checkbox" name="auto" ${settings.autoAdvance!==false?'checked':''}><span>Crossfade automático nas playlists de arquivos locais</span></label><div class="transition-explainer"><strong>YouTube: saída → carregamento → entrada</strong><p>O fade de entrada aguarda o estado de reprodução. A rede, os anúncios e o próprio vídeo ainda podem gerar um intervalo. Ambientes locais continuam tocando.</p><strong>Arquivos locais: sobreposição real</strong><p>A próxima faixa é pré-carregada e pode entrar antes da anterior terminar.</p></div>`,onSubmit:form=>{settings.musicFadeIn=Number(form.get('fadeIn'));settings.musicFadeOut=Number(form.get('fadeOut'));settings.autoAdvance=form.has('auto');ctx.commit();}});}
